-- =============================================================================
-- VNL 2024 - INITIALISATION DE LA BASE DE DONNÉES
-- Volleyball Nations League | MSc2 Manager Data Marketing
-- =============================================================================
-- Ce fichier crée la base, les tables et insère les données brutes.
-- Les requêtes SELECT, vues et procédures sont dans le dossier requetes/
-- Exécution : une seule fois pour initialiser la base
-- =============================================================================

CREATE DATABASE IF NOT EXISTS vnl2024;
USE vnl2024;

DROP TABLE IF EXISTS player_scores;
DROP TABLE IF EXISTS player_stats;
DROP TABLE IF EXISTS players;
DROP TABLE IF EXISTS teams;

-- =============================================================================
-- CRÉATION DES TABLES
-- =============================================================================

CREATE TABLE teams (
    team_id     INT PRIMARY KEY AUTO_INCREMENT,
    code        VARCHAR(3)   NOT NULL UNIQUE,
    country     VARCHAR(50)  NOT NULL,
    continent   VARCHAR(30)  NOT NULL,
    population  BIGINT,
    flag_url    VARCHAR(200)
);

CREATE TABLE players (
    player_id   INT PRIMARY KEY AUTO_INCREMENT,
    name        VARCHAR(100) NOT NULL,
    team_id     INT          NOT NULL,
    position    VARCHAR(5)   NOT NULL,
    height      INT,
    birth_year  INT,
    FOREIGN KEY (team_id) REFERENCES teams(team_id)
);

CREATE TABLE player_stats (
    stat_id         INT PRIMARY KEY AUTO_INCREMENT,
    player_id       INT         NOT NULL,
    stat_category   VARCHAR(20) NOT NULL,
    total_points    FLOAT,
    error_count     FLOAT,
    attempts        FLOAT,
    match_avg       FLOAT,
    efficiency_pct  FLOAT,
    total_actions   FLOAT,
    FOREIGN KEY (player_id) REFERENCES players(player_id),
    CONSTRAINT uq_player_category UNIQUE (player_id, stat_category)
);

CREATE TABLE IF NOT EXISTS player_scores (
    score_id     INT PRIMARY KEY AUTO_INCREMENT,
    player_id    INT          NOT NULL,
    name         VARCHAR(100),
    team_code    VARCHAR(3),
    position     VARCHAR(5),
    height       INT,
    birth_year   INT,
    score_attack FLOAT,
    score_serve  FLOAT,
    score_block  FLOAT,
    pps          FLOAT,
    segment      VARCHAR(20),
    FOREIGN KEY (player_id) REFERENCES players(player_id)
);

